def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def is_seq(x):
        return isinstance(x, (list, tuple))

    def pos(x, default=(0, 0)):
        if is_seq(x) and len(x) >= 2:
            return x[0], x[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def best_by_distance(items, origin, reverse=False):
        best = None
        best_score = None
        for it in items or []:
            p = pos(it, None)
            if p is None:
                continue
            score = manhattan(origin, p)
            if best is None or (score > best_score if reverse else score < best_score):
                best = p
                best_score = score
        return best

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name", "") or obs.get("env_name", "") or ""
    sx, sy = pos(obs.get("self_position", obs.get("agent_position", (0, 0))), (0, 0))
    ox, oy = pos(obs.get("opponent_position", obs.get("enemy_position", (sx, sy))), (sx, sy))
    w = obs.get("grid_width", obs.get("width", 0)) or 0
    h = obs.get("grid_height", obs.get("height", 0)) or 0

    # Resource collection: go to nearest resource, otherwise toward opponent/center.
    resource_keys = ("resources", "resource_positions", "targets", "food", "collectibles", "items")
    resources = None
    for k in resource_keys:
        v = obs.get(k)
        if v:
            resources = v
            break

    # Territory control: prefer frontier/unclaimed/opponent-side cells.
    territory_keys = ("frontier_cells", "unclaimed_cells", "target_cells", "opponent_territory", "neutral_cells")
    territory = None
    for k in territory_keys:
        v = obs.get(k)
        if v:
            territory = v
            break

    role = obs.get("self_role", obs.get("role", ""))
    if env == "pursuit_evasion":
        if role == "pursuer" or role == 0 or role == "chaser":
            return move_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
