            if target is not None:
                return move_toward((sx, sy), target)
        if w and h:
            center = (w // 2, h // 2)
            return move_toward((sx, sy), center)
        return move_toward((sx, sy), (ox, oy)) if (sx, sy) != (ox, oy) else [0, 0]

    if resources:
        target = best_by_distance(resources, (sx, sy))
        if target is not None:
            return move_toward((sx, sy), target)

    allies = obs.get("allied_positions", obs.get("teammate_positions", obs.get("ally_positions", []))) or []
    ally = best_by_distance(allies, (sx, sy))
    if ally is not None and ally != (sx, sy):
